import redis.clients.jedis.Jedis;
import redis.clients.jedis.resps.StreamEntry;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class RedisArchitectureDemo {
    public static void main(String[] args) {
        try (Jedis jedis = new Jedis("localhost", 6379)) {
            // 1. String with TTL
            jedis.setex("session:user123", 30, "auth_token_xyz");

            // 2. Hash
            Map<String, String> userFields = new HashMap<>();
            userFields.put("name", "Jane Doe");
            userFields.put("role", "ENGINEER");
            jedis.hset("user:123", userFields);

            // 3. Sorted Set (Leaderboard)
            jedis.zadd("leaderboard", 1500.0, "player_one");
            jedis.zadd("leaderboard", 2300.0, "player_two");

            // 4. Streams (Event Sourcing)
            Map<String, String> eventData = new HashMap<>();
            eventData.put("eventType", "ORDER_PLACED");
            eventData.put("orderId", "ord_98765");
            String entryId = jedis.xadd("order-stream", null, eventData);
            System.out.println("Dispatched event to stream with ID: " + entryId);
        }
    }
}
